const cmds = [
  ["find . -name AGENTS.md -not -path './node_modules/*' -not -path './.git/*' | head -20", "/home/kali/Desktop/Request-Rider"],
  ["git status --short | head -40", "/home/kali/Desktop/Request-Rider"],
  ["ls -la", "/home/kali/Desktop/Request-Rider"],
  ["tail -60 SESSION-CLAIMS.md 2>/dev/null || echo 'NO SESSION-CLAIMS'", "/home/kali/Desktop/Request-Rider"],
];
const out = [];
for (const [c, w] of cmds) {
  const r = await tools.shell({ command: c, workdir: w });
  out.push(`$ ${c}\n${r.output ?? r}\n`);
}
return out.join("\n");

