// Tool navigation selects a workspace; History and Traffic remain shared views.
document.querySelectorAll('nav .nav-tab').forEach(link => {
  const handleLinkNavigation = event => {
    const tab = link.dataset.tab;
    if (!tab) return;
    if (event.defaultPrevented) return;
    if (event.button === 1 || event.metaKey || event.ctrlKey || event.shiftKey) return;
    // Leaving Traffic must release its long-lived server connection instead of
    // holding it for the rest of the session. This runs before the workspace
    // branch below, which returns early: most tool tabs (Target, Intruder,
    // OSINT, Scanner, Automation, ...) are workspace kinds, so a check placed
    // after that branch would never fire for them.
    if (tab !== 'traffic') stopTrafficStream();
    if (workspaceKinds.includes(tab)) {
      event.preventDefault();
      const current = workspaceContexts.get(activeWorkspaceId);
      const target = [...workspaceContexts.values()].find(context => context.kind === tab);
      if (current) current.state = captureWorkspaceState(current.kind);
      selectWorkspace(target.id);
      return;
    }
    event.preventDefault();
    document.querySelectorAll('nav .nav-tab,.tab').forEach(item => item.classList.remove('active'));
    link.classList.add('active');
    $(tab).classList.add('active');
    if (tab === 'history') loadHistoryWithFilters();
    if (tab === 'traffic') { loadTraffic(); startTrafficStream(); }
  };
  link.addEventListener('click', handleLinkNavigation);
});

