#!/usr/bin/env python
"""Вимірює, у якому просторі жив час pointer (clientY) та innerHeight при body{zoom}."""
import json
from playwright.sync_api import sync_playwright

BASE = "http://127.0.0.1:8000/"
probe = """
() => {
  window.__probe = {};
  document.addEventListener('pointermove', e => {
    window.__probe.lastClientY = e.clientY;
    window.__probe.lastPageY = e.pageY;
  }, true);
  return {zoom: getComputedStyle(document.body).zoom};
}
"""

with sync_playwright() as p:
    b = p.firefox.launch(headless=True)
    ctx = b.new_context(viewport={"width": 1356, "height": 652})
    page = ctx.new_page()
    page.goto(BASE, wait_until="domcontentloaded")
    page.click('nav .nav-tab[data-tab="history"]')
    page.wait_for_timeout(500)
    info = page.evaluate(probe)
    # 1. де реальний CSS-блок 560 (100vh-92)?
    geo = page.evaluate("""
    () => {
      const z = parseFloat(getComputedStyle(document.body).zoom) || 1;
      const insp = document.querySelector('#history.active > .inspector');
      const r = insp.getBoundingClientRect();
      return {zoom: z, rectHeight: r.height, innerHeight: window.innerHeight,
              computedHeight: getComputedStyle(insp).height};
    }
    """)
    page.mouse.move(400, 300)
    page.wait_for_timeout(120)
    page.mouse.move(400, 301)
    page.wait_for_timeout(120)
    ptr = page.evaluate("() => window.__probe")
    print(json.dumps({"probe": info, "geo": geo, "pointer": ptr}, indent=2))
    b.close()

