func (s *server) lookupSourceIP(ctx context.Context) string {
	if s.transport == nil && s.routes == nil {
		return ""
	}
	// The external-IP check is a courtesy lookup for one status field, and it
	// must never be the reason an operation waits. An endpoint that accepts the
	// connection and stalls — which is what an unreachable resolver looks like —
	// used to hold the caller for as long as the socket stayed open, so a run
	// sat in `running` with no error. The bound is per request, overridable, and
	// it never shortens a value the operator supplied.
	lookupContext, cancel := context.WithTimeout(ctx, sourceIPLookupTimeout())
	defer cancel()
	// The slot is taken on the deadline context, not on the caller's: the caller
	// is deliberately cancellation-immune (startSourceIPLookup passes a context
	// built with context.WithoutCancel), so waiting on the caller's context for a
	// free slot could outlive every deadline this lookup actually has.
	//
	// This path already runs inside its own goroutine — one per logical exchange —
	// so waiting here queues those goroutines instead of opening thousands of
	// sockets, and the queue drains at the bound rather than at the endpoint's
	// rate. That is where the explosion was: 443 lookups and up to 102
	// simultaneous TLS connections in one 986-template run.
	if !takeSourceIPLookupSlot(lookupContext) {
		return ""
	}
	defer func() { <-sourceIPLookupSlots }()
	return s.lookupSourceIPWithSlot(lookupContext)
}

