#!/usr/bin/env python
"""Перевірка: КОЖЕН інструмент пише source_ip у Traffic.

Інструменти: Repeater, Intruder, OSINT, Scanner (3 види), AI, Automation, Corpus.
Кожен запускається проти живого рушія, потім читається /events і рахується,
скільки подій цього інструмента мають source_ip.
"""
import json
import subprocess
import sys
import time
import urllib.request

BASE = "http://127.0.0.1:8081"


def api(path, payload=None, method=None, timeout=120):
    url = BASE + path
    data = json.dumps(payload).encode() if payload is not None else None
    req = urllib.request.Request(url, data=data, method=method or ("POST" if data else "GET"),
                                 headers={"Content-Type": "application/json"})
    with urllib.request.urlopen(req, timeout=timeout) as r:
        return r.status, r.read().decode()


def clear():
    try:
        api("/events", method="DELETE")
    except Exception as e:
        print("clear failed:", e)


def events():
    _, body = api("/events")
    return json.loads(body)


def report(name, run, wait=9):
    clear()
    time.sleep(1)
    try:
        status, body = run()
        ok_api = status == 200
    except Exception as e:
        print(f"{name:14} ЗАПУСК НЕ ВДАВСЯ: {e}")
        return False
    time.sleep(wait)
    ev = events()
    total = len(ev)
    with_ip = [e for e in ev if (e.get("source_ip") or "").strip()]
    verdict = "OK" if with_ip and len(with_ip) == total else ("ЧАСТКОВО" if with_ip else "ПОРОЖНЬО")
    print(f"{name:14} http={ok_api} подій={total:4} з source_ip={len(with_ip):4}  → {verdict}")
    return verdict == "OK"


results = {}

# --- Corpus (source=tool) ---
results["corpus"] = report("corpus", lambda: api("/proxy/scanner/corpus/run", {
    "url": "https://example.com/", "max_checks": 2, "capture_context": "chk-corpus"}))

# --- Scanner local (source=tool) ---
def scanner_local():
    # ендпоінт сканера потребує завантажених шаблонів; якщо немає — повідомляємо
    return api("/proxy/scanner/local/run", {"target": "https://example.com/",
                                            "capture_context": "chk-scanlocal"})
try:
    results["scanner_local"] = report("scanner-local", scanner_local)
except Exception as e:
    print("scanner-local:", e)

# --- OSINT ---
def osint_subdomains():
    return api("/proxy/osint/transform", {
        "transform": "subdomains", "value": "example.com",
        "capture_context": "chk-osint"})
try:
    results["osint"] = report("osint", osint_subdomains, wait=14)
except Exception as e:
    print("osint:", e)

# --- Repeater (source=repeater) ---
def repeater():
    return api("/api/execute", {
        "url": "https://example.com/", "method": "GET", "raw": "",
        "capture_context": "chk-repeater"})
try:
    results["repeater"] = report("repeater", repeater)
except Exception as e:
    print("repeater:", e)

print()
print("ПІДСУМОК:", json.dumps(results, ensure_ascii=False))
ok = sum(1 for v in results.values() if v == "OK")
print(f"OK: {ok} з {len(results)}")

