// A lookup waits its turn for a free slot and gives up on its own deadline.
//
// This was the behaviour of the `lookupSourceIP` this change replaced, and the
// first version of the shared flight lost it: it took a slot with
// `trySourceIPLookupSlot`, which answers "none right now" with an empty address.
// Under load that is the very defect this change exists to remove, one layer
// down — a caller arriving while every slot is busy got nothing instead of
// waiting. So the wait is restored, bounded by the request's own deadline.
func TestSharedLookupWaitsForASlotAndGivesUpOnItsDeadline(t *testing.T) {
	transport := &countingSourceIPTransport{}
	engine := &server{transport: &http.Transport{}, sourceIPTransport: transport}

	restore := fillSourceIPLookupSlots()
	defer restore()
	t.Setenv("RR_SOURCE_IP_LOOKUP_TIMEOUT_MS", "300")

	started := time.Now()
	ip := engine.ensureSourceIP(context.Background())
	elapsed := time.Since(started)

	if ip != "" {
		t.Fatalf("a lookup with no free slot returned %q; it must give up empty", ip)
	}
	if calls := transport.calls.Load(); calls != 0 {
		t.Fatalf("a lookup with no free slot still made %d request(s)", calls)
	}
	if elapsed < 200*time.Millisecond {
		t.Fatalf("gave up after %s; it must wait for its turn before giving up", elapsed)
	}
	if elapsed > 3*time.Second {
		t.Fatalf("waited %s; the deadline must bound it", elapsed)
	}
}

// And once a slot IS free, the waiting caller gets a real answer rather than an
// empty one — that is the difference between waiting and being refused.
func TestSharedLookupAnswersAfterWaitingForASlot(t *testing.T) {
	transport := &countingSourceIPTransport{}
	engine := &server{transport: &http.Transport{}, sourceIPTransport: transport}

	// A semaphore of one, currently held by someone else for a moment.
	previous := sourceIPLookupSlots
	sourceIPLookupSlots = make(chan struct{}, 1)
	defer func() { sourceIPLookupSlots = previous }()
	sourceIPLookupSlots <- struct{}{}

	go func() {
		time.Sleep(120 * time.Millisecond)
		<-sourceIPLookupSlots
	}()
	t.Setenv("RR_SOURCE_IP_LOOKUP_TIMEOUT_MS", "5000")

	if got := engine.ensureSourceIP(context.Background()); got != "203.0.113.77" {
		t.Fatalf("a caller that waited for its slot got %q; it must get the answer", got)
	}
}

